     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.time.LocalDate;
     4	import java.time.temporal.ChronoUnit;
     5	
     6	import org.springframework.samples.petclinic.model.Owner;
     7	
     8	/**
     9	 * Scores an owner's membership. Points start at 0 and add 2 for a present email, 1 when the
    10	 * namesake count is 0, 2 for a household of 3 or more and 3 for tenure over 365 days. The
    11	 * numeric level maps those points as 1 (0-1), 2 (2-3), 3 (4-5) and 4 (6 or more).
    12	 */
    13	public final class MembershipLevel {
    14	
    15	    private static final long TENURE_DAYS_FOR_POINTS = 365;
    16	
    17	    private MembershipLevel() {
    18	    }
    19	
    20	    public static int points(Owner owner, int namesakeCount, int householdSize) {
    21	        int points = 0;
    22	        if (owner.getEmail() != null) {
    23	            points += 2;
    24	        }
    25	        if (namesakeCount == 0) {
    26	            points += 1;
    27	        }
    28	        if (householdSize >= 3) {
    29	            points += 2;
    30	        }
    31	        if (hasTenure(owner)) {
    32	            points += 3;
    33	        }
    34	        return points;
    35	    }
    36	
    37	    public static int level(int points) {
    38	        return Math.min(points / 2 + 1, 4);
    39	    }
    40	
    41	    private static boolean hasTenure(Owner owner) {
    42	        LocalDate registration = owner.getRegistrationDate();
    43	        return registration != null
    44	                && ChronoUnit.DAYS.between(registration, LocalDate.now()) > TENURE_DAYS_FOR_POINTS;
    45	    }
    46	}

