    19	    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built,
    20	            Out<Boolean> sharesHousehold)
    21	            throws InvalidTelephoneException, AddressRequiredException, FutureRegistrationDateException {
    22	        request.setTelephone(E164.normalize(request.getTelephone()));
    23	        AddressForm.apply(request);
    24	        Owner owner = ownerMapper.toOwner(request);
    25	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
    26	            throw new FutureRegistrationDateException("registrationDate must not be later than the current date");
    27	        }
    28	        LocalDate registrationDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
    29	        owner.setRegistrationDate(BusinessDay.rollForward(registrationDate));
    30	        built.set(owner);
    31	        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
    32	    }
    33	}

