     9	
    10	/**
    11	 * Derives the stable identifier shared by every owner in the same household. A household
    12	 * is the set of owners with the same last name and postcode: the first 12 hex characters of
    13	 * SHA-256 over {@code normalizedLastName + '|' + postcode} (last name normalized
    14	 * case-insensitively with collapsed whitespace, matching {@link EnsureOwnerHouseholdUnique}),
    15	 * so joiners created with {@code sharesHousehold} always resolve to the same value.
    16	 */
    17	public final class HouseholdId {
    18	
    19	    private HouseholdId() {
    20	    }
    21	
    22	    public static String of(Owner owner) {
    23	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
    24	        String seed = key(owner.getLastName()) + "|" + postcode;
    25	        try {
    26	            byte[] digest = MessageDigest.getInstance("SHA-256")
    27	                    .digest(seed.getBytes(StandardCharsets.UTF_8));
    28	            StringBuilder sb = new StringBuilder(12);
    29	            for (int i = 0; i < 6; i++) {
    30	                sb.append(String.format("%02X", digest[i]));
    31	            }
    32	            return sb.toString();
    33	        }
    34	        catch (NoSuchAlgorithmException e) {
    35	            throw new IllegalStateException(e);
    36	        }
    37	    }
    38	
    39	    private static String key(String value) {
    40	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    41	    }
    42	}

===== E164.java =====
     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
     4	
     5	/**
     6	 * Normalises a telephone number to E.164 form: keep a leading '+' and country code
     7	 * when present, otherwise assume '+61' and drop a single leading '0' from the national
     8	 * digits. Spaces, dashes and brackets are stripped; 8 to 15 digits must remain.
     9	 */
    10	final class E164 {
    11	
    12	    private E164() {
    13	    }
    14	
    15	    static String normalize(String telephone) throws InvalidTelephoneException {
    16	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
    17	        String digits;
    18	        if (cleaned.startsWith("+")) {
    19	            digits = cleaned.substring(1);
    20	        } else {
    21	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
    22	            digits = "61" + national;
    23	        }
    24	        if (!digits.matches("\\d{8,15}")) {
    25	            throw new InvalidTelephoneException("Telephone cannot be formatted as E.164");
    26	        }
    27	        requireNationalLength(digits);
    28	        return "+" + digits;
    29	    }
    30	
    31	    /**
    32	     * Enforce the national-number length required by the country code: '+61' needs 9
    33	     * national digits, '+1' needs 10. Unknown country codes are left unchecked.
    34	     */
    35	    private static void requireNationalLength(String digits) throws InvalidTelephoneException {
