     3	/**
     4	 * Computes the Luhn check digit (0-9) over the digits contained in a customer code,
     5	 * doubling from the rightmost digit. Returns {@code null} when the code is absent, so
     6	 * owners without a customer code carry no check digit.
     7	 */
     8	public final class CheckDigit {
     9	
